package com.company.platform.order.api;
import com.company.platform.order.application.*;import com.company.platform.order.domain.Order;import com.company.platform.order.api.OrderController.OrderResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/checkout") public class CheckoutController{private final CheckoutOrchestrator checkout;private final OrderService orders;public CheckoutController(CheckoutOrchestrator c,OrderService o){checkout=c;orders=o;}public record CheckoutRequest(UUID cartId){}private OrderResponse dto(Order o){return OrderResponse.of(o);}@PostMapping @PreAuthorize("hasAuthority('ORDER_CREATE')")public OrderResponse execute(@RequestBody CheckoutRequest r){return dto(checkout.execute(r.cartId()));}@PostMapping("/validate") @PreAuthorize("hasAuthority('ORDER_CREATE')")public Object validate(@RequestBody CheckoutRequest r){var c=checkout.validate(r.cartId());return java.util.Map.of("valid",true,"cartId",c.id());}@GetMapping("/{orderId}") @PreAuthorize("hasAuthority('ORDER_READ')")public OrderResponse get(@PathVariable UUID orderId){return dto(orders.get(orderId));}}
